# Writes docs/mis_polynomial/mis_conditions_order5.tex: the order conditions Σ_i b̂_i d_i(t) = 1/γ(t) (mis_theory.tex,
# Theorem 5.1) for all bicoloured trees of order ≤ 5 of the general problem class, generated by MIS.latex_conditions.
#
#     julia --project=. examples/mis_conditions_tex.jl [p] [class]

using MultiRate
const M = MultiRate.MIS
p = length(ARGS) >= 1 ? parse(Int, ARGS[1]) : 5
class = length(ARGS) >= 2 ? Symbol(ARGS[2]) : :G
dir = joinpath(@__DIR__, "..", "docs", "mis_polynomial")
name = class == :G ? "mis_conditions_order$p" : "mis_conditions_order$(p)_$class"
cls = Dict(:G => "general \$F(y,z)\$", :B => "affine in \$z\$, \$F=f(y)+B(y)z\$",
           :BA => "affine plus additive, \$F=f(y)+B(y)z+g(z)\$", :A => "additive", :L => "constant linear fast part")[class]
open(joinpath(dir, "$name.tex"), "w") do io
    print(io, raw"""
\documentclass[10pt,a4paper]{article}
\usepackage{amsmath,amssymb,booktabs,longtable,forest}
\usepackage[margin=2cm,landscape]{geometry}
\forestset{
  b/.style={circle,draw=black,fill=black,inner sep=1.1pt},
  w/.style={circle,draw=black,fill=white,inner sep=1.1pt},
  bitree/.style={for tree={grow=90,s sep=2pt,l=4pt,l sep=0pt,parent anchor=center,child anchor=center,edge={thin}},baseline}}
\newcommand{\btree}[1]{\begin{forest}bitree #1\end{forest}}
\newcommand{\dd}{\,\mathrm{d}}
\begin{document}
""")
    println(io, "\\section*{Order conditions of MIS methods with polynomial coupling up to order $p ($cls)}")
    print(io, raw"""
Supplement to \emph{Multirate infinitesimal step methods with polynomial coupling}. Conditions
$\sum_i\hat b_id_i(t)=1/\gamma(t)$ of Theorem~5.1 with $d_i(t)$ as listed; $\eta_j(u)=(\Lambda d(u))_j$,
$\zeta_i(\sigma;u)=\sum_j(\alpha_{ij}+G_{ij}(\sigma))\eta_j(u)+\int_0^\sigma(\dots)$ for the subtrees $u$ drawn inline,
$z_i=\zeta_i(\cdot;\bullet)$, $c_j=\eta_j(\bullet)$. Column R: F = holds automatically in the restart class.
Generated by \texttt{MultiRate.MIS.latex\_conditions}.

""")
    print(io, M.latex_conditions(p; class))
    println(io, "\\end{document}")
end
println("wrote $name.tex")
